import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const book: Book = {
  id: 'book-1',
  title: 'The Left Hand of Darkness',
  author: 'Ursula K. Le Guin',
  status: 'reading',
};

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: book.title })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText(book.author)).toBeInTheDocument();
  });

  it('renders status badge with correct data-status attribute', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    const badge = screen.getByText(book.status);
    expect(badge).toHaveAttribute('data-status', book.status);
  });

  it('calls onClick with the book id when clicked', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    await userEvent.click(screen.getByRole('button', { name: `${book.title} by ${book.author}` }));
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith(book.id);
  });

  it('calls onClick with the book id when Enter is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    const card = screen.getByRole('button', { name: `${book.title} by ${book.author}` });
    card.focus();
    await userEvent.keyboard('{Enter}');
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith(book.id);
  });

  it('does not call onClick when a non-Enter key is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    const card = screen.getByRole('button', { name: `${book.title} by ${book.author}` });
    card.focus();
    await userEvent.keyboard('{Space}');
    expect(handleClick).not.toHaveBeenCalled();
  });

  it('exposes an accessible label combining title and author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: 'The Left Hand of Darkness by Ursula K. Le Guin' })
    ).toBeInTheDocument();
  });
});
